CREATE TYPE "public"."content_section_key" AS ENUM('hero', 'about', 'projects-presentation', 'timeline', 'technologies', 'contact', 'media-resume');--> statement-breakpoint
ALTER TYPE "public"."project_operation_kind" ADD VALUE 'save_content_draft' BEFORE 'publish';--> statement-breakpoint
CREATE TABLE "content_section_drafts" (
	"section_key" "content_section_key" PRIMARY KEY NOT NULL,
	"document" jsonb NOT NULL,
	"revision" bigint DEFAULT 1 NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "content_section_drafts_revision_positive" CHECK ("content_section_drafts"."revision" > 0),
	CONSTRAINT "content_section_drafts_document_object" CHECK (jsonb_typeof("content_section_drafts"."document") = 'object')
);
--> statement-breakpoint
CREATE TABLE "published_content_sections" (
	"section_key" "content_section_key" PRIMARY KEY NOT NULL,
	"document" jsonb NOT NULL,
	CONSTRAINT "published_content_sections_document_object" CHECK (jsonb_typeof("published_content_sections"."document") = 'object')
);
--> statement-breakpoint
ALTER TABLE "project_operations" DROP CONSTRAINT "project_operations_target_matches_kind";--> statement-breakpoint
ALTER TABLE "project_operations" ADD COLUMN "content_section_key" "content_section_key";--> statement-breakpoint
ALTER TABLE "project_operations" ADD CONSTRAINT "project_operations_target_matches_kind" CHECK (("project_operations"."kind"::text = 'save_project_draft' AND "project_operations"."project_id" IS NOT NULL AND "project_operations"."content_section_key" IS NULL) OR ("project_operations"."kind"::text = 'save_content_draft' AND "project_operations"."project_id" IS NULL AND "project_operations"."content_section_key" IS NOT NULL) OR ("project_operations"."kind"::text IN ('save_featured_draft', 'publish') AND "project_operations"."project_id" IS NULL AND "project_operations"."content_section_key" IS NULL));
--> statement-breakpoint
INSERT INTO "content_section_drafts" ("section_key", "document") VALUES
('hero', '{"browserTitle":"Vite + React","name":"Jhon Lay Lopez","brand":"JL","role":"Application Developer to Software Engineer","heroRole":"Application Developer","location":"Pasay, Philippines","navigation":[{"label":"Home","href":"/#home"},{"label":"About","href":"/#about"},{"label":"Projects","href":"/#projects"},{"label":"Experience","href":"/#experience"},{"label":"Skills","href":"/#skills"},{"label":"Contact","href":"/#contact"}],"sectionTag":"Case No. 001 - Open File","title":"Web & Mobile","description":"I build practical web and mobile applications with clean interfaces, dependable workflows, and a growing focus on AI and DevOps.","resumeButtonLabel":"Download Portfolio","scrollCue":"Descend"}'::jsonb),
('about', '{"eyebrow":"01 - Subject Profile","title":"The Case File","lead":"A cleaner record of who I am, what I build, and where I am aiming next.","paragraphs":["I’m an Application Developer with hands-on experience building and maintaining full-stack web applications using technologies such as Next.js, React, NestJS, TypeScript, Python, and PostgreSQL.","In my current role at DFNN Inc., I work across frontend and backend development, build internal systems and dashboards, integrate third-party services such as the Google Maps API, and automate stakeholder reporting using Python and Google Cloud Platform services like BigQuery and Cloud Run Functions.","I enjoy building practical software that solves real business problems and continuously improving how I work through modern development practices, cloud technologies, DevOps, and AI-assisted development.","My goal is to continue growing as a full-stack software engineer, taking on more complex systems and building reliable, scalable applications that create real value for users and businesses."],"facts":[{"label":"Education","value":"BS Information Technology"},{"label":"Current Company","value":"DFNN Inc."},{"label":"Focus","value":"Web, Mobile, AI, DevOps"},{"label":"Status","value":"Open to Work"}],"stamp":"CLEARED","photoCaptionPrefix":"Subject on record -"}'::jsonb),
('projects-presentation', '{"eyebrow":"02 - Evidence Board","title":"Open Case Files","lead":"Pinned, threaded, and ready for inspection. These projects are the main proof of work.","allProjectsLinkLabel":"View All Projects","backLinkLabel":"Back to Home","groups":[{"category":"Personal Project","eyebrow":"01 - Independent Work","title":"Personal Projects"},{"category":"Work Project","eyebrow":"02 - Professional Work","title":"Work Projects","emptyText":"Work projects will be added here soon."},{"category":"Capstone Project","eyebrow":"03 - Team Work","title":"Capstone Projects"}]}'::jsonb),
('timeline', '{"eyebrow":"03 - Field Notes","title":"Timeline","lead":"A record of my professional experience and education.","entries":[{"role":"Application Developer","organization":"DFNN Inc.","location":"BGC, Taguig City","date":"September 2025 - Present","detail":"Built full-stack LottoMatik features and automated agent sales and lottery reporting with BigQuery and Google Cloud Platform."},{"role":"Frontend Developer Intern","organization":"DigiPlus Interactive Corp.","location":"BGC, Taguig City","date":"March 2025 - June 2025","detail":"Developed responsive Vue.js interfaces, reusable components, and API-integrated workflows with Element Plus and Pinia."},{"role":"BS in Information Technology","organization":"Polytechnic University of the Philippines","location":"PUP-Taguig","date":"2021 - 2025","detail":"Completed a Bachelor of Science in Information Technology."}]}'::jsonb),
('technologies', '{"eyebrow":"04 - Tools of the Trade","title":"The Arsenal","lead":"Technologies I use across frontend, backend, data, cloud, and testing.","groups":[{"category":"Frontend","technologies":[{"name":"TypeScript","iconKey":"typescript"},{"name":"JavaScript","iconKey":"javascript"},{"name":"React","iconKey":"react"},{"name":"Next.js","iconKey":"nextjs"},{"name":"Vue.js","iconKey":"vue"},{"name":"Material UI","iconKey":"material-ui"},{"name":"Tailwind CSS","iconKey":"tailwind-css"}]},{"category":"Backend","technologies":[{"name":"Node.js","iconKey":"nodejs"},{"name":"NestJS","iconKey":"nestjs"},{"name":"REST APIs"},{"name":"Cloudflare Workers","iconKey":"cloudflare-workers"}]},{"category":"Databases & Data","technologies":[{"name":"PostgreSQL","iconKey":"postgresql"},{"name":"Cloudflare D1"},{"name":"BigQuery","iconKey":"bigquery"}]},{"category":"Cloud & DevOps","technologies":[{"name":"Google Cloud Platform","iconKey":"google-cloud"},{"name":"Cloudflare","iconKey":"cloudflare"},{"name":"GitHub Actions","iconKey":"github-actions"}]},{"category":"Testing & Tools","technologies":[{"name":"Playwright"},{"name":"Git","iconKey":"git"},{"name":"GitHub","iconKey":"github"},{"name":"OAuth"},{"name":"JWT","iconKey":"jwt"}]}]}'::jsonb),
('contact', '{"eyebrow":"05 - Make Contact","title":"Open a Line","availability":"Open to work, collaborations, and software engineering opportunities.","noteTitle":"Leave Word","noteBody":"Send a message about internship opportunities, collaborations, or software projects worth building.","email":"jhonlaylopez.2003@gmail.com","socialLinks":[{"label":"GitHub","href":"https://github.com/Lopez-JhonLay","iconKey":"github"},{"label":"LinkedIn","href":"http://www.linkedin.com/in/jhon-lay-lopez","iconKey":"linkedin"},{"label":"Facebook","href":"https://www.facebook.com/jhonlay.lopez.1","iconKey":"facebook"}],"footerPrimary":"(c) 2026 Jhon Lay Lopez - Case file active","footerSecondary":"Built in the dark. Reads fine in the light."}'::jsonb),
